precision highp float;
precision highp int;
uniform sampler2D tDiffuse;
uniform vec2 Offset;
uniform int RepeatMode;
uniform float Rotation;
uniform vec2 Multiplier;
uniform vec2 Anchor;

vec4 premultiplyColor(vec4 colorValue) {
    float alpha = clamp(colorValue.a, 0.0, 1.0);
    return vec4(colorValue.rgb * alpha, alpha);
}

vec4 sourceOverColor(vec4 backgroundColor, vec3 effectColor, float effectAlpha) {
    float sourceAlpha = clamp(effectAlpha, 0.0, 1.0);
    float backgroundAlpha = clamp(backgroundColor.a, 0.0, 1.0);
    float remainingBackground = backgroundAlpha * (1.0 - sourceAlpha);
    float outputAlpha = sourceAlpha + remainingBackground;
    vec3 outputColor = effectColor * sourceAlpha + backgroundColor.rgb * remainingBackground;
    return vec4(outputColor, outputAlpha);
}

varying vec2 vUvScaled;


vec2 wrap(vec2 uv, int mode) {
    if (mode == 0) {
        return clamp(uv, 0.0, 1.0);
    } else if (mode == 1) {
        return mod(uv, 1.0); 
    } else if (mode == 2) {
        vec2 m = mod(uv, 2.0);
        return 1.0 - abs(m - 1.0);
    } else {
        return uv;
    }
}

void main()
{
vec4 sourceTexel = texture2D(tDiffuse, vUvScaled);
    const float ASPECT_RATIO = 16.0 / 9.0;
    const float DEG_TO_RAD = 3.14159265359 / 180.0;

    float rotationRad = Rotation * DEG_TO_RAD;

    vec2 anchorPoint = vec2(0.5) + Anchor;

    vec2 localUv = vUvScaled - anchorPoint; 

    vec2 scaledUv = localUv * Multiplier; 

    vec2 adjustedUv = scaledUv;
    adjustedUv.x *= ASPECT_RATIO;

    float c = cos(rotationRad);
    float s = sin(rotationRad);

    vec2 rotatedUv;
    rotatedUv.x = adjustedUv.x * c - adjustedUv.y * s;
    rotatedUv.y = adjustedUv.x * s + adjustedUv.y * c;

    vec2 finalRotatedUv = rotatedUv;
    finalRotatedUv.x /= ASPECT_RATIO;

    vec2 shiftedUv = finalRotatedUv + anchorPoint - Offset;

    if (RepeatMode == 3) {
        if (shiftedUv.x < 0.0 || shiftedUv.x > 1.0 || 
            shiftedUv.y < 0.0 || shiftedUv.y > 1.0) {
            gl_FragColor = vec4(0.0, 0.0, 0.0, 1.0); 
            return;
        }
    }

    vec2 wrappedUv = wrap(shiftedUv, RepeatMode);

    vec4 texel = texture2D(tDiffuse, wrappedUv);

    if (RepeatMode != 3) {
        gl_FragColor = premultiplyColor(texel);
    }
}

precision highp float;
precision highp int;
uniform sampler2D tDiffuse;
uniform float Rotation;
uniform vec2 Offset;
uniform float Repeat;
uniform float RepeatScale;
uniform int BlendOrder;
uniform vec3 StartColor;
uniform vec3 EndColor;

vec4 premultiplyColor(vec4 colorValue) {
    float alpha = clamp(colorValue.a, 0.0, 1.0);
    return vec4(colorValue.rgb * alpha, alpha);
}

vec4 sourceOverColor(vec4 backgroundColor, vec3 effectColor, float effectAlpha) {
    float sourceAlpha = clamp(effectAlpha, 0.0, 1.0);
    float backgroundAlpha = clamp(backgroundColor.a, 0.0, 1.0);
    float remainingBackground = backgroundAlpha * (1.0 - sourceAlpha);
    float outputAlpha = sourceAlpha + remainingBackground;
    vec3 outputColor = effectColor * sourceAlpha + backgroundColor.rgb * remainingBackground;
    return vec4(outputColor, outputAlpha);
}

varying vec2 vUvScaled;


vec4 blendColors(vec4 baseColor, vec4 overlayColor) {
    float sourceAlpha = clamp(overlayColor.a, 0.0, 1.0);
    float backgroundAlpha = clamp(baseColor.a, 0.0, 1.0);
    float remainingBackground = backgroundAlpha * (1.0 - sourceAlpha);
    float outputAlpha = sourceAlpha + remainingBackground;
    vec3 outputColor = overlayColor.rgb * sourceAlpha + baseColor.rgb * (1.0 - sourceAlpha);
    return vec4(outputColor, outputAlpha);
}
const float PI = 3.141592653589793;
const float ASPECT = 16.0 / 9.0;

vec2 rotateAspect(vec2 uv, float angle, vec2 center) {
  uv -= center;
  uv.x *= ASPECT;
  float rad = radians(angle);
  float cosA = cos(rad);
  float sinA = sin(rad);
  uv = mat2(cosA, -sinA, sinA, cosA) * uv;
  uv.x /= ASPECT;
  uv += center;
  return uv;
}

vec2 scaleUV(vec2 uv, float scale, vec2 center) {
  return (uv - center) / scale + center;
}

void main()
{
vec4 sourceTexel = texture2D(tDiffuse, vUvScaled);
  vec2 offsetPixels = Offset / vec2(-1920.0, -1080.0);
  vec4 color = vec4(0.0);
  vec2 center = vec2(0.5);
  float angleIncrement = Rotation / float(Repeat);
  vec2 offsetIncrement = offsetPixels / float(Repeat);
  float scaleIncrement = (RepeatScale - 1.0) / float(Repeat);

  if (BlendOrder == 0) {
    for (int i = 0; i < 1000; ++i) {
      if (float(i) >= Repeat) break;
      float t = float(i) / max(Repeat - 1.0, 1.0);
      vec3 blendedColor = mix(StartColor, EndColor, t);
      float angle = float(i) * angleIncrement;
      vec2 offset = float(i) * offsetIncrement;
      float scale = 1.0 + float(i) * scaleIncrement;
      vec2 uv = scaleUV(vUvScaled + offset, scale, center);
      vec2 rotatedUV = rotateAspect(uv, -angle, center);
      float alpha = texture2D(tDiffuse, rotatedUV).a;
      vec4 texel = vec4(blendedColor, alpha);
      color = blendColors(color, texel);
    }
  } else {
    for (int i = 999; i >= 0; --i) {
      if (float(i) >= Repeat) continue;
      float t = float(i) / max(Repeat - 1.0, 1.0);
      vec3 blendedColor = mix(StartColor, EndColor, t);
      float angle = float(i) * angleIncrement;
      vec2 offset = float(i) * offsetIncrement;
      float scale = 1.0 + float(i) * scaleIncrement;
      vec2 uv = scaleUV(vUvScaled + offset, scale, center);
      vec2 rotatedUV = rotateAspect(uv, -angle, center);
      float alpha = texture2D(tDiffuse, rotatedUV).a;
      vec4 texel = vec4(blendedColor, alpha);
      color = blendColors(color, texel);
    }
  }

  gl_FragColor = color;
}

