precision highp float;
precision highp int;
uniform sampler2D tDiffuse;
uniform float Opacity;
uniform vec2 Scale;
uniform float Rotation;
uniform vec2 Position;
uniform float GridSize;
uniform float BoxScaleMin;
uniform float BoxScaleMax;
uniform vec3 Color;

vec4 premultiplyColor(vec4 colorValue) {
    float alpha = clamp(colorValue.a, 0.0, 1.0);
    return vec4(colorValue.rgb * alpha, alpha);
}

vec4 sourceOverColor(vec4 backgroundColor, vec3 effectColor, float effectAlpha) {
    float sourceAlpha = clamp(effectAlpha, 0.0, 1.0);
    float backgroundAlpha = clamp(backgroundColor.a, 0.0, 1.0);
    float remainingBackground = backgroundAlpha * (1.0 - sourceAlpha);
    float outputAlpha = sourceAlpha + remainingBackground;
    vec3 outputColor = effectColor * sourceAlpha + backgroundColor.rgb * remainingBackground;
    return vec4(outputColor, outputAlpha);
}

varying vec2 vUvScaled;
vec2 objectUv;

vec2 standardObjectUv(vec2 uv) {
    vec2 p = uv * 2.0 - 1.0;
    p -= Position;
    p.x *= 16.0 / 9.0;

    float standardRotation = Rotation * 3.14159265359 / 180.0;
    p = vec2(
        cos(standardRotation) * p.x + sin(standardRotation) * p.y,
        -sin(standardRotation) * p.x + cos(standardRotation) * p.y
    );
    p /= max(abs(Scale), vec2(0.0001));
    p.x /= 16.0 / 9.0;
    return p * 0.5 + 0.5;
}

void main()
{
objectUv = standardObjectUv(vUvScaled);
vec4 sourceTexel = texture2D(tDiffuse, vUvScaled);
if (Opacity <= 0.0) { gl_FragColor = premultiplyColor(sourceTexel); return; }
    float aspectRatio = 16.0 / 9.0;


    vec2 centeredCoord = objectUv - vec2(0.5);


    centeredCoord.x *= aspectRatio;


    vec2 cellUV = centeredCoord * GridSize;
    vec2 cellCoord = floor(cellUV + 0.5); 
    vec2 cellFract = fract(cellUV + 0.5);


    vec2 cellCenterCoord = cellCoord / GridSize;

    cellCenterCoord.x /= aspectRatio;
    vec2 originalUV = cellCenterCoord + vec2(0.5);

    vec3 centerColor = texture2D(tDiffuse, originalUV).rgb;
    float value = max(max(centerColor.r, centerColor.g), centerColor.b);
    float dynamicBoxScale = mix(BoxScaleMin, BoxScaleMax, value);

    vec2 centerStart = vec2(0.5) - dynamicBoxScale / 2.0;
    vec2 centerEnd   = vec2(0.5) + dynamicBoxScale / 2.0;

    bool inBox = all(greaterThanEqual(cellFract, centerStart)) &&
                 all(lessThanEqual(cellFract, centerEnd));

    if (inBox) {
        gl_FragColor = sourceOverColor(sourceTexel, Color, Opacity);
    } else {
        gl_FragColor = premultiplyColor(sourceTexel);
    }
}

precision highp float;
precision highp int;
uniform sampler2D tDiffuse;
uniform float Power;

vec4 premultiplyColor(vec4 colorValue) {
    float alpha = clamp(colorValue.a, 0.0, 1.0);
    return vec4(colorValue.rgb * alpha, alpha);
}

vec4 sourceOverColor(vec4 backgroundColor, vec3 effectColor, float effectAlpha) {
    float sourceAlpha = clamp(effectAlpha, 0.0, 1.0);
    float backgroundAlpha = clamp(backgroundColor.a, 0.0, 1.0);
    float remainingBackground = backgroundAlpha * (1.0 - sourceAlpha);
    float outputAlpha = sourceAlpha + remainingBackground;
    vec3 outputColor = effectColor * sourceAlpha + backgroundColor.rgb * remainingBackground;
    return vec4(outputColor, outputAlpha);
}

varying vec2 vUvScaled;


float easeInOutPower(float t, float p) {
  if (t < 0.5) {
    return 0.5 * pow(2.0 * t, p);
  } else {
    return 1.0 - 0.5 * pow(2.0 * (1.0 - t), p);
  }
}

void main()
{
vec4 sourceTexel = texture2D(tDiffuse, vUvScaled);
  vec4 texel = texture2D(tDiffuse, vUvScaled);
  float eased = easeInOutPower(vUvScaled.x, Power);
  gl_FragColor = sourceOverColor(sourceTexel, vec3(eased), 1.0);
}

precision highp float;
precision highp int;
uniform sampler2D tDiffuse;
uniform vec2 P1;
uniform vec2 P2;
uniform vec2 P3;
uniform float GeometryScale;

vec4 premultiplyColor(vec4 colorValue) {
    float alpha = clamp(colorValue.a, 0.0, 1.0);
    return vec4(colorValue.rgb * alpha, alpha);
}

vec4 sourceOverColor(vec4 backgroundColor, vec3 effectColor, float effectAlpha) {
    float sourceAlpha = clamp(effectAlpha, 0.0, 1.0);
    float backgroundAlpha = clamp(backgroundColor.a, 0.0, 1.0);
    float remainingBackground = backgroundAlpha * (1.0 - sourceAlpha);
    float outputAlpha = sourceAlpha + remainingBackground;
    vec3 outputColor = effectColor * sourceAlpha + backgroundColor.rgb * remainingBackground;
    return vec4(outputColor, outputAlpha);
}

varying vec2 vUvScaled;


bool isInTriangle(vec2 p, vec2 p0, vec2 p1, vec2 p2) {
    vec2 v0 = p2 - p0;
    vec2 v1 = p1 - p0;
    vec2 v2 = p - p0;

    float d00 = dot(v0, v0);
    float d01 = dot(v0, v1);
    float d11 = dot(v1, v1);
    float d20 = dot(v2, v0);
    float d21 = dot(v2, v1);
    float denom = d00 * d11 - d01 * d01;
    float v = (d11 * d20 - d01 * d21) / denom;
    float w = (d00 * d21 - d01 * d20) / denom;
    float u = 1.0 - v - w;

    return (u >= 0.0) && (v >= 0.0) && (w >= 0.0);
}

void main()
{
vec4 sourceTexel = texture2D(tDiffuse, vUvScaled);
    vec2 p1Uv = vec2(P1[0]/1920.0+0.5, P1[1]/1080.0+0.5);
    vec2 p2Uv = vec2(P2[0]/1920.0+0.5, P2[1]/1080.0+0.5);
    vec2 p3Uv = vec2(P3[0]/1920.0+0.5, P3[1]/1080.0+0.5);

    vec2 centeredUV = vUvScaled - 0.5;
    vec2 scaledUV = centeredUV / GeometryScale + 0.5;

    if (isInTriangle(scaledUV, p1Uv, p2Uv, p3Uv)) {
        gl_FragColor = vec4(0.0);
    } else {
        vec4 texel = texture2D(tDiffuse, vUvScaled);
        gl_FragColor = premultiplyColor(texel);
    }
}

precision highp float;
precision highp int;
uniform sampler2D tDiffuse;
uniform float Opacity;
uniform vec2 Scale;
uniform float Rotation;
uniform vec2 Position;
uniform vec2 P1;
uniform vec2 P2;
uniform float Width;
uniform vec3 Color;
uniform int Stroke;
uniform float PatternRotation;

vec4 premultiplyColor(vec4 colorValue) {
    float alpha = clamp(colorValue.a, 0.0, 1.0);
    return vec4(colorValue.rgb * alpha, alpha);
}

vec4 sourceOverColor(vec4 backgroundColor, vec3 effectColor, float effectAlpha) {
    float sourceAlpha = clamp(effectAlpha, 0.0, 1.0);
    float backgroundAlpha = clamp(backgroundColor.a, 0.0, 1.0);
    float remainingBackground = backgroundAlpha * (1.0 - sourceAlpha);
    float outputAlpha = sourceAlpha + remainingBackground;
    vec3 outputColor = effectColor * sourceAlpha + backgroundColor.rgb * remainingBackground;
    return vec4(outputColor, outputAlpha);
}

varying vec2 vUvScaled;
vec2 objectUv;

vec2 standardObjectUv(vec2 uv) {
    vec2 p = uv * 2.0 - 1.0;
    p -= Position;
    p.x *= 16.0 / 9.0;

    float standardRotation = Rotation * 3.14159265359 / 180.0;
    p = vec2(
        cos(standardRotation) * p.x + sin(standardRotation) * p.y,
        -sin(standardRotation) * p.x + cos(standardRotation) * p.y
    );
    p /= max(abs(Scale), vec2(0.0001));
    p.x /= 16.0 / 9.0;
    return p * 0.5 + 0.5;
}

const float ASPECT = 9.0 / 16.0;
const float DEG2RAD = 3.14159265359 / 180.0;

vec2 rotate(vec2 p, float angle) {
    float c = cos(angle);
    float s = sin(angle);
    return vec2(p.x * c - p.y * s, p.x * s + p.y * c);
}

void main() {
objectUv = standardObjectUv(vUvScaled);
vec4 sourceTexel = texture2D(tDiffuse, vUvScaled);
if (Opacity <= 0.0) { gl_FragColor = premultiplyColor(sourceTexel); return; }
    vec4 texel = texture2D(tDiffuse, vUvScaled);

    vec2 p1 = vec2(P1.x / 1920.0, P1.y / 1080.0);
    vec2 p2 = vec2(P2.x / 1920.0, P2.y / 1080.0);
    vec2 uv = objectUv - 0.5;

    vec2 p1Corrected = vec2(p1.x, p1.y * ASPECT);
    vec2 p2Corrected = vec2(p2.x, p2.y * ASPECT);
    vec2 uvCorrected = vec2(uv.x, uv.y * ASPECT);

    float rad = PatternRotation * DEG2RAD;
    p1Corrected = rotate(p1Corrected, rad);
    p2Corrected = rotate(p2Corrected, rad);

    vec2 dir = p2Corrected - p1Corrected;
    float len = length(dir);
    vec2 dirNorm = normalize(dir);

    vec2 toPoint = uvCorrected - p1Corrected;

    float projDist = dot(toPoint, dirNorm);

    vec2 projPoint = p1Corrected + projDist * dirNorm;
    float perpDist = length(uvCorrected - projPoint);

    float w = Width / 100.0;

    bool draw = false;

    if (Stroke == 0) {
        if (projDist >= 0.0 && projDist <= len && perpDist < w) {
            draw = true;
        }
    } else if (Stroke == 1) {
        float tClamped = clamp(projDist / len, 0.0, 1.0);
        vec2 closestPoint = p1Corrected + tClamped * dir;
        float dist = length(uvCorrected - closestPoint);
        if (dist < w) {
            draw = true;
        }
    } else if (Stroke == 2) {
        if (projDist >= -w && projDist <= len + w && perpDist < w) {
            draw = true;
        }
    }

    if (draw) {
        gl_FragColor = sourceOverColor(sourceTexel, Color, Opacity);
    } else {
        gl_FragColor = premultiplyColor(texel);
    }
}

